head.b:skin:
/* ============================================================
   FP-SMART — DESIGN TOKENS · Thème "NOVA"
   Direction : plateforme edtech moderne et interactive —
   dégradés indigo/sarcelle, cartes flottantes, glassmorphism
   doux, typographie géométrique, micro-animations.
   Toutes les variables gardent leur nom d'origine : aucune
   règle de composant ni aucun script n'a besoin d'être modifié.
   ============================================================ */

:root {
  /* --- Palette --- */
  --paper: #f4f6fc;          /* fond général, gris-bleu très clair */
  --paper-dark: #e8ecf8;
  --ink: #161a2e;            /* texte principal, encre bleu-nuit */
  --ink-soft: #5b6178;
  --kraft: #dbe1f5;          /* bordures douces */
  --kraft-line: #e6eaf8;
  --green: #4f46e5;          /* couleur d'action principale — indigo électrique */
  --green-dark: #3730a3;
  --gold: #f59e0b;           /* accent / mise en avant — ambre */
  --gold-light: #fbbf24;
  --red-stamp: #ef4444;      /* alerte / suppression */
  --cream-card: #ffffff;
  --surface: #ffffff;
  --shadow-color: rgba(79, 70, 229, 0.16);

  /* --- Accents supplémentaires (badges, illustrations) --- */
  --teal: #0d9488;
  --violet: #7c3aed;
  --blue: #2563eb;
  --coral: #fb7185;
  --gradient-brand: linear-gradient(135deg, #4f46e5 0%, #0d9488 100%);
  --gradient-warm: linear-gradient(135deg, #f59e0b 0%, #fb7185 100%);

  /* --- Type scale --- */
  --font-display: 'Sora', 'Tajawal', sans-serif;
  --font-body: 'Inter', 'Tajawal', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  --fs-xs: 0.75rem;
  --fs-sm: 0.875rem;
  --fs-base: 1rem;
  --fs-md: 1.125rem;
  --fs-lg: 1.375rem;
  --fs-xl: 1.875rem;
  --fs-2xl: 2.5rem;
  --fs-3xl: 3.5rem;

  /* --- Spacing --- */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;
  --space-8: 3rem;
  --space-10: 4rem;
  --space-12: 6rem;

  /* --- Misc --- */
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 22px;
  --border-w: 1.5px;
  --transition: 220ms cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1240px;
}

[data-theme="dark"] {
  --paper: #0a0c18;
  --paper-dark: #06070f;
  --ink: #eef1fb;
  --ink-soft: #a2a8c4;
  --kraft: #262c4d;
  --kraft-line: #1c2140;
  --green: #818cf8;
  --green-dark: #6366f1;
  --gold: #fbbf24;
  --gold-light: #fde68a;
  --red-stamp: #f87171;
  --cream-card: #12142a;
  --surface: #10122333;
  --surface: #10132a;
  --shadow-color: rgba(0, 0, 0, 0.55);
  --teal: #2dd4bf;
  --violet: #a78bfa;
  --blue: #60a5fa;
  --coral: #fb7185;
}

/* ============================================================
   RESET
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; }
ul, ol { margin: 0; padding: 0; list-style: none; }
h1, h2, h3, h4, p { margin: 0; }
input, select, textarea, button { font-size: inherit; }

html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

body {
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: var(--fs-base);
  line-height: 1.6;
  transition: background var(--transition), color var(--transition);
  background-image:
    radial-gradient(ellipse 900px 500px at 8% -5%, rgba(79, 70, 229, 0.10), transparent 55%),
    radial-gradient(ellipse 900px 500px at 100% 0%, rgba(13, 148, 136, 0.10), transparent 55%),
    radial-gradient(ellipse 700px 500px at 50% 100%, rgba(245, 158, 11, 0.06), transparent 55%);
  background-attachment: fixed;
}

/* RTL handling */
html[dir="rtl"] body { font-family: 'Tajawal', 'Inter', sans-serif; }
html[dir="rtl"] .ltr-only { direction: ltr; unicode-bidi: isolate; }

:focus-visible {
  outline: 2.5px solid var(--gold);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ============================================================
   SIGNATURE TEXTURE — dot-grid subtil (remplace le "papier ligné")
   ============================================================ */
.paper-texture {
  background-image: radial-gradient(var(--kraft-line) 1.4px, transparent 1.4px);
  background-size: 22px 22px;
  background-position: 0 6px;
}

.stamp {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  border: none;
  color: #fff;
  border-radius: 50px;
  padding: var(--space-2) var(--space-4);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: var(--fs-sm);
  letter-spacing: 0.02em;
  background: var(--gradient-brand);
  box-shadow: 0 8px 20px var(--shadow-color);
  animation: floatBadge 4.5s ease-in-out infinite;
}

[data-theme="dark"] .stamp { color: #fff; }

@keyframes floatBadge {
  0%, 100% { transform: translateY(0) rotate(-1deg); }
  50% { transform: translateY(-5px) rotate(1deg); }
}

/* ============================================================
   TYPOGRAPHY
   ============================================================ */
.font-display {
  font-family: var(--font-display);
}

h1, h2, h3, .heading {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.02em;
}

html[dir="rtl"] h1, html[dir="rtl"] h2, html[dir="rtl"] h3, html[dir="rtl"] .heading {
  font-family: 'Tajawal', sans-serif;
  letter-spacing: 0;
  font-weight: 800;
}

.eyebrow {
  font-size: var(--fs-xs);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--gold);
  font-weight: 800;
}
html[dir="rtl"] .eyebrow { text-transform: none; letter-spacing: 0.02em; }

/* ============================================================
   LAYOUT
   ============================================================ */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-5);
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--gradient-brand);
  color: #fff;
  padding: var(--space-2) var(--space-4);
  z-index: 200;
  border-radius: 0 0 var(--radius-sm) 0;
}
.skip-link:focus { left: var(--space-3); top: var(--space-3); }

/* ============================================================
   HEADER
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  border-bottom: var(--border-w) solid var(--kraft);
  backdrop-filter: blur(12px) saturate(160%);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  padding: var(--space-3) 0;
}

.brand {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.brand-seal {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.brand-name {
  font-family: var(--font-display);
  font-size: var(--fs-lg);
  font-weight: 800;
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.brand-tagline {
  font-size: var(--fs-xs);
  color: var(--ink-soft);
}

.main-nav {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.nav-link {
  position: relative;
  padding: var(--space-2) var(--space-3);
  font-weight: 700;
  font-size: var(--fs-sm);
  color: var(--ink-soft);
  border-radius: 50px;
  transition: color var(--transition), background var(--transition);
  white-space: nowrap;
}

.nav-link:hover { color: var(--green); background: rgba(79, 70, 229, 0.08); }
.nav-link.active { color: #fff; background: var(--gradient-brand); box-shadow: 0 6px 16px var(--shadow-color); }
.nav-link.active::after { content: none; }

.header-controls {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-md);
  border: var(--border-w) solid var(--kraft);
  background: var(--surface);
  color: var(--ink);
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.icon-btn:hover { border-color: var(--green); transform: translateY(-2px); box-shadow: 0 6px 14px var(--shadow-color); }
.icon-btn svg { width: 18px; height: 18px; }

.lang-switch {
  display: flex;
  border: var(--border-w) solid var(--kraft);
  border-radius: 50px;
  overflow: hidden;
}
.lang-btn {
  padding: var(--space-2) var(--space-3);
  background: var(--surface);
  color: var(--ink-soft);
  font-weight: 800;
  font-size: var(--fs-xs);
  border: none;
  transition: background var(--transition), color var(--transition);
}
.lang-btn.active { background: var(--gradient-brand); color: #fff; }
.lang-btn:not(.active):hover { background: var(--paper-dark); }

.mobile-nav-toggle { display: none; }

@media (max-width: 900px) {
  .main-nav { display: none; }
  .mobile-nav-toggle { display: inline-flex; }
}
/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  padding: var(--space-10) 0 var(--space-8);
  overflow: hidden;
}
.hero::before, .hero::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
  opacity: 0.5;
  z-index: -1;
  pointer-events: none;
}
.hero::before {
  width: 420px; height: 420px;
  background: radial-gradient(circle, rgba(79,70,229,0.35), transparent 70%);
  top: -160px; inset-inline-end: -120px;
  animation: driftBlob 12s ease-in-out infinite;
}
.hero::after {
  width: 360px; height: 360px;
  background: radial-gradient(circle, rgba(13,148,136,0.30), transparent 70%);
  bottom: -140px; inset-inline-start: -100px;
  animation: driftBlob 14s ease-in-out infinite reverse;
}
@keyframes driftBlob {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(20px, -18px) scale(1.08); }
}

.hero-inner {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: var(--space-8);
  align-items: center;
}

@media (max-width: 900px) {
  .hero-inner { grid-template-columns: 1fr; }
}

.hero-eyebrow-row {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: var(--space-4);
}

.hero h1 {
  font-size: clamp(2rem, 4.2vw, var(--fs-3xl));
  line-height: 1.08;
  margin-bottom: var(--space-4);
}

.hero-subtitle {
  font-size: var(--fs-md);
  color: var(--ink-soft);
  max-width: 540px;
  margin-bottom: var(--space-6);
}

.search-bar {
  display: flex;
  gap: var(--space-2);
  max-width: 520px;
}

.search-bar input {
  flex: 1;
  padding: var(--space-3) var(--space-4);
  border: 2px solid var(--kraft);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--ink);
  font-size: var(--fs-base);
  transition: border-color var(--transition);
}
.search-bar input:focus { border-color: var(--green); }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-md);
  border: 2px solid transparent;
  font-weight: 700;
  font-size: var(--fs-sm);
  transition: transform var(--transition), box-shadow var(--transition), background var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--gradient-brand);
  color: #fff;
  background-size: 140% 140%;
  background-position: 0% 50%;
}
.btn-primary:hover { background-position: 100% 50%; transform: translateY(-2px); box-shadow: 0 8px 22px rgba(79, 70, 229, 0.4); }

.btn-secondary {
  background: transparent;
  border-color: var(--kraft);
  color: var(--ink);
}
.btn-secondary:hover { border-color: var(--gold); color: var(--gold); transform: translateY(-2px); }

.btn-ghost {
  background: transparent;
  color: var(--ink-soft);
}
.btn-ghost:hover { color: var(--green); }

.hero-stats {
  display: flex;
  gap: var(--space-6);
  margin-top: var(--space-6);
}
.hero-stat-num {
  font-family: var(--font-display);
  font-size: var(--fs-2xl);
  font-weight: 800;
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.hero-stat-label {
  font-size: var(--fs-xs);
  color: var(--ink-soft);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* The "dossier" signature visual */
.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
}

.dossier-stack {
  position: relative;
  width: 320px;
  height: 380px;
}

.dossier-card {
  position: absolute;
  width: 280px;
  height: 360px;
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft);
  border-radius: var(--radius-lg);
  box-shadow: 0 24px 50px var(--shadow-color);
  padding: var(--space-5);
  animation: floatCard 6s ease-in-out infinite;
}
.dossier-card.back-1 { transform: rotate(-7deg) translate(-18px, 10px); opacity: 0.85; animation-delay: 0.4s; }
.dossier-card.back-2 { transform: rotate(6deg) translate(20px, 18px); opacity: 0.65; animation-delay: 0.8s; }
.dossier-card.front {
  z-index: 2;
  background: var(--surface);
  border-image: var(--gradient-brand) 1;
}
@keyframes floatCard {
  0%, 100% { translate: 0 0; }
  50% { translate: 0 -10px; }
}
@media (prefers-reduced-motion: reduce) { .dossier-card { animation: none; } }

.dossier-line {
  height: 9px;
  background: var(--kraft-line);
  border-radius: 50px;
  margin-bottom: var(--space-3);
}
.dossier-line:nth-child(1) { background: var(--gradient-brand); opacity: 0.85; }
.dossier-line.short { width: 60%; }
.dossier-line.tiny { width: 35%; height: 7px; }

.dossier-stamp-seal {
  position: absolute;
  bottom: var(--space-5);
  right: var(--space-5);
  width: 76px;
  height: 76px;
  filter: drop-shadow(0 6px 14px var(--shadow-color));
}
html[dir="rtl"] .dossier-stamp-seal { right: auto; left: var(--space-5); }

/* ============================================================
   SECTION HEADERS
   ============================================================ */
.section {
  padding: var(--space-10) 0;
}
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
  flex-wrap: wrap;
}
.section-header h2 {
  font-size: var(--fs-2xl);
}

/* ============================================================
   SUBJECT / LEVEL QUICK GRID (home)
   ============================================================ */
.quick-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-4);
}

.quick-tile {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  padding: var(--space-5);
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft);
  border-radius: var(--radius-lg);
  transition: transform var(--transition), border-color var(--transition), box-shadow var(--transition);
}
.quick-tile:hover {
  transform: translateY(-5px) scale(1.015);
  border-color: transparent;
  box-shadow: 0 16px 32px var(--shadow-color);
}
.quick-tile-icon {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  background: var(--gradient-brand);
  color: #fff;
  transition: transform var(--transition);
}
.quick-tile:hover .quick-tile-icon { transform: rotate(-6deg) scale(1.08); }
.quick-tile-icon svg { width: 22px; height: 22px; }
.quick-tile-name { font-weight: 700; font-family: var(--font-display); font-size: var(--fs-md); }
.quick-tile-count { font-size: var(--fs-xs); color: var(--ink-soft); }
.level-category {
  grid-column: 1 / -1;
  display: block;
}
.level-category .quick-tile {
  flex-direction: row;
  align-items: center;
  gap: var(--space-4);
  cursor: pointer;
  position: relative;
}
.expand-icon {
  margin-left: auto;
  color: var(--ink-soft);
  transition: transform var(--transition);
}
.level-category .quick-tile.expanded .expand-icon { transform: rotate(180deg); }
.level-category.cat-empty .quick-tile { cursor: default; opacity: 0.5; }
.level-category.cat-empty .quick-tile:hover { border-color: var(--border-subtle); }
.level-subgrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-4);
  margin-top: var(--space-3);
}
.sub-tile { background: var(--bg-subtle); border-color: var(--border-subtle); }
.sub-tile:hover { border-color: var(--green); }
.level-subgrid .quick-tile {
  flex-direction: column;
  align-items: stretch;
  gap: var(--space-3);
}

/* ============================================================
   CASCADE PANEL (home page drill-down)
   ============================================================ */
.cascade-panel {
  background: var(--surface);
  border: 1px solid var(--kraft-line);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  animation: fadeIn 0.2s ease;
}
.cascade-panel .cascade-level + .cascade-level {
  margin-top: var(--space-4);
  padding-top: var(--space-4);
  border-top: 1px solid var(--kraft-line);
}
.cascade-panel .quick-tile {
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.cascade-panel .quick-tile:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.12);
}
.cascade-panel .cascade-back {
  font-size: var(--fs-xs);
  padding: var(--space-1) var(--space-2);
}
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ============================================================
   LIBRARY GROUP (library page — docs grouped by diploma)
   ============================================================ */
.library-group + .library-group {
  margin-top: var(--space-8);
  padding-top: var(--space-6);
  border-top: 2px solid var(--kraft-line);
}
.library-group-header {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: var(--space-4);
}
.library-group-header h3 {
  font-family: var(--font-display);
  font-size: var(--fs-xl);
  margin: 0;
  color: var(--ink);
}
.library-group-count {
  font-size: var(--fs-xs);
  font-weight: 600;
  color: var(--ink-soft);
  background: var(--cream-card);
  padding: 2px var(--space-2);
  border-radius: 50px;
}

/* ============================================================
   FILTER BAR (library page)
   ============================================================ */
.filters-bar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  align-items: center;
  padding: var(--space-4);
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft);
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-6);
}

.filter-select {
  padding: var(--space-2) var(--space-3);
  border: 2px solid var(--kraft);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--ink);
  font-weight: 600;
  font-size: var(--fs-sm);
  min-width: 140px;
  transition: border-color var(--transition);
}
.filter-select:focus { border-color: var(--green); }

.filters-meta {
  margin-left: auto;
  font-size: var(--fs-sm);
  color: var(--ink-soft);
  font-weight: 600;
}
html[dir="rtl"] .filters-meta { margin-left: 0; margin-right: auto; }

/* ============================================================
   DOCUMENT GRID + CARD
   ============================================================ */
.doc-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
  gap: var(--space-5);
}
.documents-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-3);
}

.doc-card {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border: var(--border-w) solid var(--kraft);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
  height: 100%;
}
.doc-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--gradient-brand);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}
.doc-card:hover::before { transform: scaleX(1); }
.doc-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 18px 36px var(--shadow-color);
}

.doc-card-head {
  padding: var(--space-4) var(--space-4) 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.doc-badge {
  font-size: var(--fs-xs);
  font-weight: 700;
  padding: 2px var(--space-2);
  border-radius: 50px;
  white-space: nowrap;
}
.doc-badge.type-bac-bem { background: rgba(239, 68, 68, 0.12); color: var(--red-stamp); }
.doc-badge.type-cours { background: rgba(79, 70, 229, 0.12); color: var(--green); }
.doc-badge.type-corriges { background: rgba(245, 158, 11, 0.15); color: var(--gold); }
.doc-badge.type-exercices { background: rgba(124, 58, 237, 0.12); color: #7c3aed; }
.doc-badge.type-devoir { background: rgba(37, 99, 235, 0.12); color: #2563eb; }
.doc-badge.type-composition { background: rgba(239, 68, 68, 0.12); color: var(--red-stamp); }
.doc-badge.type-examens { background: rgba(239, 68, 68, 0.12); color: var(--red-stamp); }
.doc-badge.type-resumes { background: rgba(13, 148, 136, 0.12); color: #0d9488; }

.doc-year {
  font-size: var(--fs-xs);
  color: var(--ink-soft);
  font-family: var(--font-mono);
}

.doc-card-body {
  padding: var(--space-3) var(--space-4);
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.doc-title {
  font-family: var(--font-display);
  font-size: var(--fs-md);
  font-weight: 600;
  line-height: 1.3;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.doc-meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  font-size: var(--fs-xs);
  color: var(--ink-soft);
}
.doc-meta-row span { display: inline-flex; align-items: center; gap: 4px; }
.doc-meta-row svg { width: 13px; height: 13px; }

.doc-card-foot {
  display: flex;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  border-top: 1px solid var(--kraft-line);
}
.doc-card-foot .btn { flex: 1; padding: var(--space-2) var(--space-3); font-size: var(--fs-xs); }

.doc-card-compact { border-radius: var(--radius-md); min-height: 0; }
.doc-card-compact .doc-card-body { padding: var(--space-3) var(--space-4); gap: var(--space-2); }
.doc-card-compact .doc-card-foot { padding: var(--space-2) var(--space-4); }
.doc-card-compact .doc-card-foot .btn { padding: var(--space-1) var(--space-2); font-size: var(--fs-xs); }

.host-tag {
  position: absolute;
  top: var(--space-3);
  inset-inline-end: var(--space-3);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 50px;
  background: var(--ink);
  color: var(--paper);
  letter-spacing: 0.05em;
}

/* ============================================================
   EMPTY STATE
   ============================================================ */
.empty-state {
  text-align: center;
  padding: var(--space-10) var(--space-4);
  color: var(--ink-soft);
}
.empty-state svg { width: 64px; height: 64px; margin: 0 auto var(--space-4); opacity: 0.4; }
.empty-state h3 { font-size: var(--fs-lg); color: var(--ink); margin-bottom: var(--space-2); }

/* ============================================================
   MODAL (preview + download)
   ============================================================ */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 17, 30, 0.6);
  display: none;
  align-items: center;
  justify-content: center;
  padding: var(--space-2);
  z-index: 1000;
  backdrop-filter: blur(3px);
}
.modal-overlay.open { display: flex; }

.modal-box {
  background: var(--surface);
  border-radius: var(--radius-lg);
  width: min(98vw, 1600px);
  height: min(96vh, 900px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: var(--border-w) solid var(--kraft);
  box-shadow: 0 30px 60px rgba(15, 17, 30, 0.4);
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-5);
  border-bottom: var(--border-w) solid var(--kraft-line);
}
.modal-head h3 { font-size: var(--fs-lg); line-height: 1.3; }

.modal-body {
  display: flex;
  flex-direction: row;
  overflow: hidden;
  flex: 1;
  min-height: 0;
}
.modal-preview { flex: 0 0 50%; min-width: 200px; }
.modal-info { flex: 1 1 50%; min-width: 200px; }
.modal-resize-handle {
  flex: 0 0 5px;
  cursor: col-resize;
  background: var(--kraft-line);
  position: relative;
  z-index: 2;
  transition: background 0.15s;
}
.modal-resize-handle:hover,
.modal-resize-handle.active { background: var(--green); }

@media (max-width: 900px) {
  .modal-body { flex-direction: column; }
  .modal-preview { flex: 0 0 50vh !important; }
  .modal-info { flex: 1 1 auto !important; }
  .modal-resize-handle { display: none; }
}

.modal-preview {
  background: var(--paper-dark);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 0;
  overflow: hidden;
}
.modal-preview iframe {
  width: 100%;
  height: 100%;
  min-height: 0;
  border: none;
}

.preview-fallback {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: var(--space-4);
  text-align: center;
  color: var(--ink-soft);
}

.modal-info {
  padding: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  overflow: hidden;
  min-height: 0;
}
.modal-info p { color: var(--ink-soft); font-size: var(--fs-sm); }

.modal-detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3);
  font-size: var(--fs-sm);
}
.modal-detail-grid dt { color: var(--ink-soft); font-size: var(--fs-xs); text-transform: uppercase; letter-spacing: 0.04em; }
.modal-detail-grid dd { font-weight: 700; margin: 0; }

.modal-actions {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.modal-close {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: var(--border-w) solid var(--kraft);
  background: var(--surface);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.modal-close:hover { border-color: var(--red-stamp); color: var(--red-stamp); }

.modal-ai-chat {
  border-top: var(--border-w) solid var(--kraft-line);
  padding-top: var(--space-2);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
.modal-ai-messages {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-2) 0;
  min-height: 0;
}
.modal-ai-messages .chat-msg {
  max-width: 80%;
}
/* Force same bot base styles as main assistant page */
.modal-ai-messages .chat-msg.bot {
  white-space: normal;
}
.modal-ai-messages .chat-msg.bot img {
  max-width: 100%;
  border-radius: var(--radius-md);
  margin-top: var(--space-1);
}
.modal-ai-input-row {
  display: flex;
  gap: var(--space-1);
  align-items: flex-end;
  flex-shrink: 0;
}
.modal-ai-input-row textarea {
  flex: 1;
  resize: none;
  padding: var(--space-2) var(--space-3);
  border: 2px solid var(--kraft);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--ink);
  font-family: inherit;
  font-size: var(--fs-xs);
  min-height: 32px;
  max-height: 80px;
  box-sizing: border-box;
}
.modal-ai-input-row textarea:focus { border-color: var(--green); }
.modal-ai-input-row .btn { padding: var(--space-2) var(--space-3); flex-shrink: 0; }
.modal-ai-tools {
  display: flex;
  gap: var(--space-1);
  flex-shrink: 0;
}
.modal-ai-tools .btn {
  font-size: var(--fs-xs);
  padding: var(--space-1) var(--space-2);
}
.modal-ai-file-tag { margin: 0; flex-shrink: 0; }

.modal-ai-suggestions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}
.modal-ai-suggestions .chip {
  font-size: 11px;
  padding: 4px 10px;
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft-line);
  border-radius: 50px;
  cursor: pointer;
  transition: border-color var(--transition);
}
.modal-ai-suggestions .chip:hover { border-color: var(--green); }

/* Fullscreen chat mode — hides everything except the chat */
.modal-box.chat-full .modal-preview { display: none; }
.modal-box.chat-full .modal-info { flex: 1 1 100% !important; }
.modal-box.chat-full .modal-body > .modal-resize-handle { display: none; }
.modal-box.chat-full .modal-info > div:not(.modal-ai-chat),
.modal-box.chat-full .eyebrow,
.modal-box.chat-full #modal-description,
.modal-box.chat-full .modal-detail-grid,
.modal-box.chat-full .modal-actions { display: none; }
.modal-box.chat-full .modal-info { padding: 0; overflow: hidden; }
.modal-box.chat-full .modal-ai-chat { border-top: none; padding: var(--space-4); flex: 1; }
.modal-box.chat-full .modal-ai-messages { flex: 1; min-height: 200px; }

/* ============================================================
   MOBILE NAV DRAWER
   ============================================================ */
.mobile-drawer {
  position: fixed;
  inset: 0;
  z-index: 150;
  display: none;
}
.mobile-drawer.open { display: block; }
.mobile-drawer-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 17, 30, 0.55);
}
.mobile-drawer-panel {
  position: absolute;
  top: 0;
  inset-inline-end: 0;
  width: min(300px, 85vw);
  height: 100%;
  background: var(--paper);
  padding: var(--space-5);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  border-inline-start: var(--border-w) solid var(--kraft);
}
.mobile-drawer .nav-link { padding: var(--space-3); font-size: var(--fs-md); }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  border-top: var(--border-w) solid var(--kraft);
  padding: var(--space-8) 0 var(--space-6);
  margin-top: var(--space-10);
}
.footer-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}
.footer-about { max-width: 480px; color: var(--ink-soft); font-size: var(--fs-sm); }
.footer-meta { font-size: var(--fs-xs); color: var(--ink-soft); text-align: end; }

/* ============================================================
   TOAST
   ============================================================ */
.toast {
  position: fixed;
  bottom: var(--space-5);
  inset-inline-start: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: var(--paper);
  padding: var(--space-3) var(--space-5);
  border-radius: 50px;
  font-size: var(--fs-sm);
  font-weight: 600;
  z-index: 2000;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition), transform var(--transition);
}
html[dir="rtl"] .toast { transform: translateX(50%) translateY(20px); }
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); pointer-events: auto; }
html[dir="rtl"] .toast.show { transform: translateX(50%) translateY(0); }

/* ============================================================
   PAGE LOAD ANIMATION (orchestrated, restrained)
   ============================================================ */
@keyframes riseIn {
  from { opacity: 0; transform: translateY(18px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.animate-in { animation: riseIn 0.5s cubic-bezier(0.4,0,0.2,1) both; }
.delay-1 { animation-delay: 0.06s; }
.delay-2 { animation-delay: 0.12s; }
.delay-3 { animation-delay: 0.18s; }

/* ============================================================
   UTILITIES
   ============================================================ */
.hidden { display: none !important; }
.text-center { text-align: center; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
}
/* ============================================================
   ASSISTANT PAGE (chat)
   ============================================================ */
.assistant-page {
  max-width: 880px;
  margin: 0 auto;
  padding: var(--space-6) var(--space-5) var(--space-10);
  display: flex;
  flex-direction: column;
  height: calc(100vh - 70px);
}

.assistant-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding-bottom: var(--space-4);
  border-bottom: var(--border-w) solid var(--kraft-line);
  margin-bottom: var(--space-4);
}

.assistant-header-text h2 { font-size: var(--fs-xl); }
.assistant-header-text p { color: var(--ink-soft); font-size: var(--fs-sm); margin-top: 4px; }

.provider-pill {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--fs-xs);
  font-weight: 700;
  padding: var(--space-2) var(--space-3);
  border-radius: 50px;
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft);
  color: var(--ink-soft);
  white-space: nowrap;
}
.provider-pill .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green); flex-shrink: 0; }
.provider-pill.off .dot { background: var(--red-stamp); }

.chat-scroll {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--space-2) var(--space-1) var(--space-4);
}

.chat-msg {
  max-width: 80%;
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-lg);
  font-size: var(--fs-sm);
  line-height: 1.55;
  white-space: pre-wrap;
}
.chat-msg {
  animation: msgIn 0.28s cubic-bezier(0.4,0,0.2,1) both;
}
@keyframes msgIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.chat-msg.user {
  align-self: flex-end;
  background: var(--gradient-brand);
  color: #fff;
  border-bottom-right-radius: 4px;
  box-shadow: 0 6px 16px var(--shadow-color);
}
html[dir="rtl"] .chat-msg.user { align-self: flex-start; border-bottom-right-radius: var(--radius-lg); border-bottom-left-radius: 4px; }

.chat-msg.bot {
  align-self: flex-start;
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft-line);
  color: var(--ink);
  border-bottom-left-radius: 4px;
  white-space: normal;
}
html[dir="rtl"] .chat-msg.bot { align-self: flex-end; border-bottom-left-radius: var(--radius-lg); border-bottom-right-radius: 4px; }

.chat-msg.system-note {
  align-self: center;
  background: transparent;
  border: 1.5px dashed var(--kraft);
  color: var(--ink-soft);
  font-size: var(--fs-xs);
  text-align: center;
}

.chat-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--ink-soft);
  gap: var(--space-3);
  padding: var(--space-6);
}
.chat-empty svg { width: 56px; height: 56px; opacity: 0.4; }

.suggestion-chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  justify-content: center;
  margin-top: var(--space-3);
}
.chip {
  padding: var(--space-2) var(--space-3);
  border-radius: 50px;
  border: var(--border-w) solid var(--kraft);
  background: var(--surface);
  font-size: var(--fs-xs);
  font-weight: 600;
  color: var(--ink);
  transition: border-color var(--transition), color var(--transition);
}
.chip:hover { border-color: var(--green); color: var(--green); }

.typing-dots {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  padding: var(--space-1) 0;
}
.typing-dots span {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--gradient-brand);
  animation: typingPulse 1.2s infinite ease-in-out;
}
.typing-dots span:nth-child(2) { animation-delay: 0.15s; }
.typing-dots span:nth-child(3) { animation-delay: 0.3s; }
@keyframes typingPulse {
  0%, 60%, 100% { opacity: 0.3; transform: translateY(0); }
  30% { opacity: 1; transform: translateY(-3px); }
}

.chat-input-row {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding-top: var(--space-4);
  border-top: var(--border-w) solid var(--kraft-line);
}
.chat-input-main {
  display: flex;
  gap: var(--space-2);
  align-items: flex-end;
}
.chat-input-main textarea {
  flex: 1;
  resize: none;
  padding: var(--space-3) var(--space-4);
  border: 2px solid var(--kraft);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--ink);
  font-family: inherit;
  font-size: var(--fs-base);
  min-height: 52px;
  max-height: 140px;
  transition: border-color var(--transition);
}
.chat-input-main textarea:focus { border-color: var(--green); }
.chat-input-main .btn-primary { align-self: flex-end; }

.chat-input-tools {
  display: flex;
  gap: var(--space-1);
  justify-content: flex-start;
}
.chat-input-tools .btn {
  font-size: var(--fs-xs);
  padding: var(--space-1) var(--space-3);
}

.chat-toolbar {
  display: flex;
  justify-content: flex-end;
  margin-bottom: var(--space-2);
}

.assistant-key-row {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-3);
}
.assistant-key-row select, .assistant-key-row input {
  flex: 1;
}
.recent-heading {
  font-size: var(--fs-xs);
  color: var(--ink-soft);
  margin-bottom: var(--space-2);
}
.recent-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.recent-item {
  padding: var(--space-1) var(--space-2);
  cursor: pointer;
  font-size: var(--fs-xs);
  color: var(--ink);
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}
.recent-item:hover { background: var(--cream-card); }

.stop-generation-btn { display: none; }
.btn-danger { background: var(--red-stamp); color: #fff; border: none; }
.btn-danger:hover { background: #dc2626; }

.chat-suggestions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  padding: var(--space-2) 0;
}
.chat-suggestions .chip {
  font-size: 11px;
  padding: 4px 10px;
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft-line);
  border-radius: 50px;
  cursor: pointer;
  transition: border-color var(--transition);
}
.chat-suggestions .chip:hover { border-color: var(--green); }

.chat-attachments {
  display: flex;
  gap: var(--space-2);
  padding-bottom: var(--space-2);
  flex-wrap: wrap;
}
.file-tag {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--fs-xs);
  font-weight: 600;
  padding: var(--space-1) var(--space-3);
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft);
  border-radius: 50px;
  color: var(--ink);
}
.file-tag svg { width: 14px; height: 14px; }
.file-remove {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  color: var(--red-stamp);
  display: inline-flex;
  align-items: center;
}
.btn-attach {
  padding: var(--space-2) var(--space-3);
  display: flex;
  align-items: center;
  cursor: pointer;
}
.btn-attach svg { width: 18px; height: 18px; }
.chat-msg.has-file { padding-top: var(--space-2); }
.chat-msg .file-tag { margin-bottom: var(--space-2); }

/* Regenerate button */
.regenerate-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  background: transparent;
  border: 1px solid var(--kraft);
  color: var(--ink-soft);
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 4px;
  cursor: pointer;
  margin-top: var(--space-2);
  margin-inline-start: var(--space-1);
  transition: color var(--transition), border-color var(--transition);
}
.regenerate-btn:hover { color: var(--green); border-color: var(--green); }
.regenerate-btn .icon svg { width: 13px; height: 13px; }

/* Copy button on bot messages */
.copy-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  background: transparent;
  border: none;
  color: var(--ink-soft);
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 4px;
  cursor: pointer;
  margin-top: var(--space-2);
  transition: color var(--transition), background var(--transition);
}
.copy-btn:hover { color: var(--green); background: rgba(79, 70, 229, 0.10); }
.copy-btn .icon svg { width: 14px; height: 14px; }
.copy-btn.copied { color: var(--green); }

/* Markdown rendered styles inside bot messages */
.chat-msg.bot h1, .chat-msg.bot h2, .chat-msg.bot h3 {
  margin: var(--space-3) 0 var(--space-2);
  font-family: var(--font-display);
  line-height: 1.3;
}
.chat-msg.bot h1 { font-size: var(--fs-lg); }
.chat-msg.bot h2 { font-size: var(--fs-md); }
.chat-msg.bot h3 { font-size: var(--fs-base); }
.chat-msg.bot p { margin: var(--space-2) 0; }
.chat-msg.bot p:first-child { margin-top: 0; }
.chat-msg.bot p:last-child { margin-bottom: 0; }
.chat-msg.bot hr { margin: var(--space-3) 0; border: none; border-top: 2px solid var(--kraft-line); }
.chat-msg.bot pre {
  background: #161a2e;
  color: #d7dcff;
  padding: var(--space-3);
  border-radius: var(--radius-md);
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  margin: var(--space-2) 0;
  white-space: pre;
}
.chat-msg.bot code {
  background: var(--kraft);
  padding: 1px 4px;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: .9em;
}
.chat-msg.bot pre code { background: none; padding: 0; font-size: var(--fs-xs); }
.chat-msg.bot blockquote {
  margin: var(--space-2) 0;
  padding: var(--space-2) var(--space-3);
  border-inline-start: 3px solid var(--gold);
  background: var(--cream-card);
  border-radius: var(--radius-sm);
  font-style: italic;
  color: var(--ink-soft);
}
.chat-msg.bot ul, .chat-msg.bot ol {
  margin: var(--space-2) 0;
  padding-inline-start: var(--space-5);
}
.chat-msg.bot li { margin: var(--space-1) 0; }
.chat-msg.bot a { color: var(--green); text-decoration: underline; }
.chat-msg.bot table {
  border-collapse: collapse;
  margin: var(--space-2) 0;
  width: 100%;
  font-size: var(--fs-sm);
}
.chat-msg.bot th, .chat-msg.bot td {
  border: 1px solid var(--kraft-line);
  padding: var(--space-2) var(--space-3);
  text-align: left;
}
html[dir="rtl"] .chat-msg.bot th, html[dir="rtl"] .chat-msg.bot td { text-align: right; }
.chat-msg.bot th { background: var(--cream-card); font-weight: 700; }
.chat-msg.bot .math-block { overflow-x: auto; margin: var(--space-2) 0; }
.chat-msg.bot .katex { font-size: 1.05em; }
.chat-msg.bot .katex-display > .katex { font-size: 1.15em; }
.chat-msg.bot .math-fallback { font-family: var(--font-mono); font-size: var(--fs-xs); color: var(--green); background: var(--green-bg); padding: 0.1em 0.3em; border-radius: var(--radius-sm); white-space: pre-wrap; }

.chat-toolbar {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}
.conv-sidebar {
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft-line);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-2);
  overflow: hidden;
}
.conv-sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-2) var(--space-3);
  border-bottom: var(--border-w) solid var(--kraft-line);
  font-size: var(--fs-sm);
}
.conv-list {
  max-height: 200px;
  overflow-y: auto;
  padding: var(--space-1) 0;
}
.conv-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-2) var(--space-3);
  cursor: pointer;
  font-size: var(--fs-xs);
  border-bottom: 1px solid var(--kraft-line);
  transition: background var(--transition);
}
.conv-item:hover { background: var(--surface); }
.conv-item.active { background: var(--surface); font-weight: 700; }
.conv-item-title { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.conv-item-actions { display: flex; gap: var(--space-1); flex-shrink: 0; }
.conv-item-actions button { padding: 2px 4px; font-size: 10px; background: none; border: 1px solid var(--kraft); border-radius: 4px; cursor: pointer; }
.saved-prompts-panel {
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft-line);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-2);
  overflow: hidden;
}
.prompt-item {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  cursor: pointer;
  font-size: var(--fs-xs);
  border-bottom: 1px solid var(--kraft-line);
  transition: background var(--transition);
}
.prompt-item:hover { background: var(--surface); }
.prompt-item-text { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* ============================================================
   ADMIN PANEL
   ============================================================ */
.admin-page {
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--space-8) var(--space-5) var(--space-10);
}

.admin-lock {
  max-width: 420px;
  margin: var(--space-10) auto;
  text-align: center;
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft);
  border-radius: var(--radius-lg);
  padding: var(--space-8) var(--space-6);
}
.admin-lock svg { width: 48px; height: 48px; color: var(--gold); margin: 0 auto var(--space-4); }
.admin-lock-form {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-top: var(--space-5);
}
.admin-lock-form input {
  padding: var(--space-3) var(--space-4);
  border: 2px solid var(--kraft);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--ink);
  text-align: center;
}
.admin-error {
  color: var(--red-stamp);
  font-size: var(--fs-sm);
  font-weight: 600;
  min-height: 1.2em;
}

.admin-section {
  background: var(--cream-card);
  border: var(--border-w) solid var(--kraft);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  margin-bottom: var(--space-5);
}
.admin-section h3 { font-size: var(--fs-md); margin-bottom: var(--space-4); display: flex; align-items: center; gap: var(--space-2); }

.form-row {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  margin-bottom: var(--space-4);
}
.form-row label { font-size: var(--fs-sm); font-weight: 700; color: var(--ink-soft); }
.form-row input, .form-row select, .form-row textarea {
  padding: var(--space-3) var(--space-4);
  border: 2px solid var(--kraft);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--ink);
  font-family: inherit;
}
.form-row textarea { min-height: 100px; resize: vertical; font-size: var(--fs-sm); }
.form-row input:focus, .form-row select:focus, .form-row textarea:focus { border-color: var(--green); }
.form-row-cols { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-4); }
@media (max-width: 600px) { .form-row-cols { grid-template-columns: 1fr; } }

.key-list { display: flex; flex-direction: column; gap: var(--space-3); }
.key-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  background: var(--surface);
  border: var(--border-w) solid var(--kraft-line);
  border-radius: var(--radius-md);
  flex-wrap: wrap;
}
.key-item-info { display: flex; flex-direction: column; gap: 2px; }
.key-item-provider { font-weight: 700; font-family: var(--font-display); }
.key-item-meta { font-size: var(--fs-xs); color: var(--ink-soft); font-family: var(--font-mono); }
.key-item-actions { display: flex; gap: var(--space-2); }
.badge-active {
  font-size: var(--fs-xs);
  font-weight: 700;
  color: var(--green);
  background: rgba(79, 70, 229, 0.12);
  padding: 2px var(--space-2);
  border-radius: 50px;
}
.btn-sm { padding: var(--space-2) var(--space-3); font-size: var(--fs-xs); }
.btn-danger { background: transparent; border: 2px solid var(--red-stamp); color: var(--red-stamp); }
.btn-danger:hover { background: var(--red-stamp); color: #fff; }

.save-confirm {
  font-size: var(--fs-sm);
  color: var(--green);
  font-weight: 700;
  opacity: 0;
  transition: opacity var(--transition);
}
.save-confirm.show { opacity: 1; }

.admin-toprow { display: flex; align-items: center; justify-content: space-between; margin-bottom: var(--space-6); flex-wrap: wrap; gap: var(--space-3); }

/* ---- Admin tabs ---- */
.admin-tabs {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-5);
  border-bottom: var(--border-w) solid var(--kraft-line);
}
.admin-tab-btn {
  padding: var(--space-3) var(--space-4);
  background: transparent;
  border: none;
  border-bottom: 3px solid transparent;
  font-weight: 700;
  font-size: var(--fs-sm);
  color: var(--ink-soft);
  transition: color var(--transition), border-color var(--transition);
}
.admin-tab-btn.active { color: var(--green); border-color: var(--green); }
.admin-tab-btn:hover { color: var(--green); }
.admin-tab-panel.hidden { display: none; }

/* ---- Doc manager table ---- */
.admin-doc-table-wrap {
  overflow-x: auto;
  margin-top: var(--space-4);
}
.admin-doc-table-wrap table {
  min-width: 1200px;
}
.admin-doc-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--fs-sm);
}
.admin-doc-table th {
  text-align: left;
  padding: var(--space-2) var(--space-3);
  color: var(--ink-soft);
  font-size: var(--fs-xs);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-bottom: var(--border-w) solid var(--kraft-line);
}
html[dir="rtl"] .admin-doc-table th { text-align: right; }
.admin-doc-table th.sortable { cursor: pointer; user-select: none; }
.admin-doc-table th.sortable:hover { color: var(--green); }
.btn-source-eye { cursor:pointer; background:none; border:none; font-size:1.1rem; padding:2px 6px; border-radius:var(--radius-sm); transition:background 0.15s; }
.btn-source-eye:hover { background:var(--kraft-line); }
.btn-preview-pdf { cursor:pointer; background:none; border:none; font-size:1rem; padding:2px 4px; border-radius:var(--radius-sm); transition:background 0.15s; }
.btn-preview-pdf:hover { background:var(--kraft-line); }
.admin-doc-table td {
  padding: var(--space-3);
  border-bottom: 1px solid var(--kraft-line);
  vertical-align: middle;
}
.doc-table-title { font-weight: 600; max-width: 260px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.doc-table-actions { display: flex; gap: var(--space-1); white-space: nowrap; flex-shrink: 0; min-width: 100px; }
.local-tag {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  background: rgba(79, 70, 229, 0.12);
  color: var(--green);
  padding: 1px 6px;
  border-radius: 50px;
  margin-inline-start: var(--space-2);
}

.admin-doc-search-row {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  flex-wrap: wrap;
  justify-content: space-between;
}

.form-row-cols-3 {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: var(--space-4);
}
@media (max-width: 700px) { .form-row-cols-3 { grid-template-columns: 1fr; } }

.export-hint {
  font-size: var(--fs-xs);
  color: var(--ink-soft);
  margin-top: var(--space-2);
}

.doc-form-actions {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  margin-top: var(--space-2);
}

.btn-ghost.active {
  background: var(--green-bg) !important;
  color: var(--green) !important;
  border-color: var(--green) !important;
}

/* Admin sub-tabs */
.admin-sub-tabs {
  display: flex;
  gap: 0;
  margin-bottom: var(--space-3);
  border-bottom: 2px solid var(--kraft-line);
}
.admin-sub-tab {
  padding: var(--space-2) var(--space-4);
  border: none;
  background: none;
  cursor: pointer;
  font-size: var(--fs-sm);
  font-weight: 600;
  color: var(--ink-soft);
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: color .15s, border-color .15s;
}
.admin-sub-tab:hover { color: var(--ink); }
.admin-sub-tab.active {
  color: var(--green);
  border-bottom-color: var(--green);
}

/* Admin collapsible sections */
.admin-collapse {
  border: var(--border-w) solid var(--kraft-line);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-3);
  overflow: hidden;
  background: var(--surface);
}
.admin-collapse-summary {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  cursor: pointer;
  font-size: var(--fs-sm);
  font-weight: 700;
  color: var(--ink);
  background: var(--cream-card);
  user-select: none;
  list-style: none;
}
.admin-collapse-summary::-webkit-details-marker { display: none; }
.admin-collapse-summary::before {
  content: '▶';
  font-size: 10px;
  color: var(--ink-soft);
  transition: transform .2s;
}
.admin-collapse[open] > .admin-collapse-summary::before { transform: rotate(90deg); }
.admin-collapse-body {
  padding: var(--space-3);
}

/* Backup tooltip */
.db-backup-item { position: relative; }
.db-backup-tooltip {
  display: none;
  position: fixed;
  z-index: 10000;
  background: var(--ink);
  color: #fff;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  font-size: var(--fs-xs);
  line-height: 1.5;
  white-space: nowrap;
  pointer-events: none;
  box-shadow: 0 4px 12px rgba(0,0,0,.25);
  max-width: min(90vw, 400px);
  overflow: hidden;
}
.db-backup-tooltip.show { display: block; }

/* ============================================================
   PASSWORD TOGGLE (eye icon)
   ============================================================ */
.pwd-toggle-wrap {
  position: relative;
  display: flex;
  align-items: center;
}
.pwd-toggle-wrap {
  position: relative;
  display: flex;
  align-items: stretch;
}
.pwd-toggle-wrap input {
  padding-right: 32px;
  width: 100%;
  box-sizing: border-box;
}
.pwd-toggle-btn {
  position: absolute;
  right: 2px;
  top: 2px;
  bottom: 2px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 2px 6px;
  color: var(--ink-soft);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  border-radius: var(--radius-sm);
}
.pwd-toggle-btn:hover { color: var(--ink); background: rgba(0,0,0,.04); }
.pwd-toggle-btn .icon svg { width: 18px; height: 18px; display: block; }

/* Masquer la section Blogger vide qui crée un espace au-dessus du header */
#main-section { display: none; }
/* Forcer le reset body (Blogger injecte margin:8px par défaut) */
body { margin: 0 !important; padding: 0 !important; }

/* ---- Responsive Admin Panel ---- */
@media (max-width: 900px) {
  .admin-tab-panel { padding: var(--space-3) !important; }
  .admin-doc-table { font-size: var(--fs-xs); }
  .admin-doc-table th, .admin-doc-table td { padding: var(--space-2) !important; }
  .admin-doc-table .doc-table-actions { flex-direction: column; gap: 4px !important; }
  .admin-doc-table .doc-table-actions button { font-size: 10px; padding: 3px 6px !important; }
}
@media (max-width: 700px) {
  .form-row-cols { grid-template-columns: 1fr !important; }
  .form-row-cols-3 { grid-template-columns: 1fr !important; }
  .admin-sub-tabs { flex-wrap: wrap; gap: 4px; }
  .admin-sub-tab { font-size: var(--fs-xs); padding: var(--space-1) var(--space-2) !important; }
  .admin-section { padding: var(--space-3) !important; }
  .admin-doc-table .doc-table-title { max-width: 140px; }
}
@media (max-width: 480px) {
  .admin-tab-bar { flex-wrap: wrap; gap: 4px; }
  .admin-tab-bar button { font-size: var(--fs-xs); padding: var(--space-2) var(--space-3) !important; flex: 1 1 45%; }
  .doc-form-actions { flex-direction: column; gap: var(--space-2); }
  .doc-form-actions button { width: 100%; }
  .admin-doc-table { display: block; overflow-x: auto; white-space: nowrap; }
  .db-backup-item { flex-direction: column; align-items: flex-start; }
}

/* ---- Responsive Front-end ---- */
@media (max-width: 700px) {
  .hero-section h1 { font-size: var(--fs-xl) !important; }
  .hero-section p { font-size: var(--fs-sm) !important; }
  .dossier-grid { grid-template-columns: 1fr !important; gap: var(--space-3) !important; }
  .recent-grid { grid-template-columns: 1fr !important; }
  .search-bar input { font-size: var(--fs-sm); }
  .filter-bar { flex-direction: column; gap: var(--space-2); }
  .filter-bar select { width: 100%; }
  .stat-card { padding: var(--space-3) !important; }
  .modal-box { width: 95vw !important; max-height: 90vh !important; margin: var(--space-2) !important; }
  .modal-info { padding: var(--space-3) !important; }
  .conv-sidebar { width: 100% !important; position: static !important; }
  .footer-content { flex-direction: column; text-align: center; gap: var(--space-3); }
}

body.script:
//
  window.FP_BASE_URL = "https://cdn.jsdelivr.net/gh/droidapk1002-beep/fp-smart-assets@main/repo/";
  window.FP_ROUTES = { home: "#home", library: "#library", assistant: "#assistant", admin: "#admin" };
//

//
/* LAYOUT — header, footer, modal, drawer */

function escapeHTML(str) {
  var m = {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'};
  return String(str).replace(/[&<>"']/g, function(c) { return m[c]; });
}

function escapeAttr(str) {
  var m = {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'};
  return String(str).replace(/[&<>"']/g, function(c) { return m[c]; });
}

/* ---- Markdown renderer (for bot messages) ---- */
function renderMarkdown(text) {
  if (!text) return '';
  var html = escapeHTML(text);
  html = html.replace(/```(\w*)\n([\s\S]*?)```/g, function(_, lang, code) {
    return '<pre><code class="lang-' + (lang || 'text') + '">' + code.trim() + '</code></pre>';
  });
  html = html.replace(/`([^`\n]+)`/g, '<code>$1</code>');
  html = html.replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>');
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');
  html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');
  html = html.replace(/^---+$/gm, '<hr>');
  html = html.replace(/^&gt; (.+)$/gm, '<blockquote>$1</blockquote>');
  html = html.replace(/^[-*] (.+)$/gm, '<li>$1</li>');
  html = html.replace(/((?:<li>.*<\/li>\n?)+)/g, '<ul>$1</ul>');
  html = html.replace(/^\d+\. (.+)$/gm, '<li>$1</li>');
  html = html.replace(/((?:<li>.*<\/li>\n?)+)/g, function(match) {
    if (match.indexOf('<ul>') >= 0) return match;
    return '<ol>' + match + '</ol>';
  });
  html = html.replace(/(\|.+\|\n)+/g, function(tableBlock) {
    var rows = tableBlock.trim().split('\n');
    if (rows.length < 2) return tableBlock;
    var headerCells = rows[0].split('|').filter(function(c) { return c.trim(); });
    var bodyStart = 1;
    if (rows.length > 1 && rows[1].split('|').filter(function(c) { return c.trim(); }).every(function(c) { return /^[\s:-]+$/.test(c); })) bodyStart = 2;
    var table = '<table><thead><tr>' + headerCells.map(function(c) { return '<th>' + c.trim() + '</th>'; }).join('') + '</tr></thead><tbody>';
    for (var i = bodyStart; i < rows.length; i++) {
      var cells = rows[i].split('|').filter(function(c) { return c.trim(); });
      table += '<tr>' + cells.map(function(c) { return '<td>' + c.trim() + '</td>'; }).join('') + '</tr>';
    }
    table += '</tbody></table>';
    return table;
  });
  html = html.replace(/\n\n(?!<)/g, '</p><p>');
  html = html.replace(/\n(?!<)/g, '<br>');
  html = '<p>' + html + '</p>';
  html = html.replace(/<p>\s*<\/p>/g, '');
  html = html.replace(/<p>(<h[1-3]>)/g, '$1');
  html = html.replace(/(<\/h[1-3]>)<\/p>/g, '$1');
  html = html.replace(/<p>(<pre>)/g, '$1');
  html = html.replace(/(<\/pre>)<\/p>/g, '$1');
  html = html.replace(/<p>(<ul>)/g, '$1');
  html = html.replace(/(<\/ul>)<\/p>/g, '$1');
  html = html.replace(/<p>(<ol>)/g, '$1');
  html = html.replace(/(<\/ol>)<\/p>/g, '$1');
  html = html.replace(/<p>(<table>)/g, '$1');
  html = html.replace(/(<\/table>)<\/p>/g, '$1');
  html = html.replace(/<p>(<blockquote>)/g, '$1');
  html = html.replace(/(<\/blockquote>)<\/p>/g, '$1');
  html = html.replace(/<p>(<hr>)<\/p>/g, '$1');
  return html;
}

/* FP_ROUTES : URLs réelles des pages (utile sur Blogger, où les pages ne
   s'appellent pas index.html/library.html mais ont une URL du type
   /p/library.html). Laisser tel quel pour un usage local/standalone. */
var FP_ROUTES = (typeof window !== 'undefined' && window.FP_ROUTES) || {
  home: 'index.html', library: 'library.html', assistant: 'assistant.html', admin: 'admin.html'
};

function renderHeader(activePage) {
  var navItems = [
    { key: 'home', href: FP_ROUTES.home },
    { key: 'library', href: FP_ROUTES.library },
    { key: 'assistant', href: FP_ROUTES.assistant }
  ];
  var navHTML = navItems.map(function(item) {
    return '<a class="nav-link ' + (activePage === item.key ? 'active' : '') + '" href="' + item.href + '">' + t('nav.' + item.key) + '</a>';
  }).join('');

  return '' +
    '<header class="site-header">' +
      '<div class="container header-inner">' +
        '<a href="' + FP_ROUTES.home + '" class="brand">' +
          '<span class="brand-name" style="font-weight:700;color:var(--green);font-size:1.3rem;">FP-SMART</span>' +
        '</a>' +
        '<nav class="main-nav" aria-label="Navigation principale">' + navHTML + '</nav>' +
        '<div class="header-controls">' +
          '<div class="lang-switch" role="group" aria-label="Langue">' +
            '<button class="lang-btn ' + (APP.lang === 'fr' ? 'active' : '') + '" data-lang="fr">FR</button>' +
            '<button class="lang-btn ' + (APP.lang === 'ar' ? 'active' : '') + '" data-lang="ar">ع</button>' +
            '<button class="lang-btn ' + (APP.lang === 'en' ? 'active' : '') + '" data-lang="en">EN</button>' +
          '</div>' +
          '<button class="icon-btn" id="theme-toggle" aria-label="Theme">' + icon(APP.theme === 'light' ? 'moon' : 'sun') + '</button>' +
          '<button class="icon-btn mobile-nav-toggle" id="mobile-nav-open" aria-label="Menu">' + icon('menu') + '</button>' +
        '</div>' +
      '</div>' +
    '</header>' +
    '<div class="mobile-drawer" id="mobile-drawer">' +
      '<div class="mobile-drawer-backdrop" id="mobile-drawer-backdrop"></div>' +
      '<div class="mobile-drawer-panel">' +
        '<button class="icon-btn" id="mobile-nav-close" style="align-self:flex-end;" aria-label="Close">' + icon('close') + '</button>' +
        navItems.map(function(item) {
          return '<a class="nav-link ' + (activePage === item.key ? 'active' : '') + '" href="' + item.href + '">' + t('nav.' + item.key) + '</a>';
        }).join('') +
      '</div>' +
    '</div>';
}

function renderFooter() {
  return '' +
    '<footer class="site-footer">' +
      '<div class="container footer-inner">' +
        '<p class="footer-about">' + (t('footer.about') || 'FP-SMART — Plateforme dédiée à la Formation Professionnelle en Algérie') + '</p>' +
        '<div class="footer-meta">' +
          '<div>&copy; ' + new Date().getFullYear() + ' FP-SMART</div>' +
          '<div>&#x1F1E9;&#x1F1FF; ' + (t('footer.madeWith') || 'Made for Algerian Vocational Training') + '</div>' +
        '</div>' +
      '</div>' +
    '</footer>';
}

