/* ============================================================
   ADMIN – API keys management
   ============================================================ */
const STORAGE_KEYS_KEY = 'fp_api_keys';
const ADMIN_PW_KEY = 'fp_admin_password';
var _adminContentWired = false;

const PROVIDERS = {
  anthropic: { label: 'Anthropic (Claude)', defaultModel: 'claude-sonnet-4-6', endpoint: 'https://api.anthropic.com/v1/messages' },
  openai:    { label: 'OpenAI (GPT)',       defaultModel: 'gpt-4.1',           endpoint: 'https://api.openai.com/v1/chat/completions' },
  google:    { label: 'Google (Gemini)',    defaultModel: 'gemini-2.5-flash',  endpoint: 'https://generativelanguage.googleapis.com/v1beta/models' },
  custom:    { label: 'Autre (compatible OpenAI)', defaultModel: '', endpoint: '' }
};

function getStoredKeys() {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEYS_KEY) || '[]'); } catch (e) { return []; }
}
function saveStoredKeys(keys) {
  localStorage.setItem(STORAGE_KEYS_KEY, JSON.stringify(keys));
}
function getActiveKey() {
  var keys = getStoredKeys();
  return keys.find(function(k) { return k.active; }) || keys[0] || null;
}
function getSelectedKey() {
  var sel = document.getElementById('key-select');
  if (!sel) return getActiveKey();
  var keyId = sel.value;
  if (!keyId) return getActiveKey();
  var keys = getStoredKeys();
  return keys.find(function(k) { return k.id === keyId; }) || getActiveKey();
}
function setSelectedKey(idx) {
  localStorage.setItem('fp_selected_key_idx', idx);
}

function sanitizeApiKey(raw) {
  return raw.replace(/[\u200B-\u200D\uFEFF]/g, '').replace(/\s+/g, '').trim();
}
function maskKey(key) {
  if (!key) return '••••••••';
  if (key.length <= 8) return '••••••••';
  return key.slice(0, 4) + '••••••••' + key.slice(-4);
}

function initAdminPanel() {
  const lockScreen = document.getElementById('admin-lock-screen');
  const content = document.getElementById('admin-content');
  const storedPw = localStorage.getItem(ADMIN_PW_KEY);

  if (!storedPw) {
    // First visit: show setup
    document.getElementById('admin-login-form').style.display = 'none';
    document.getElementById('admin-setup-form').style.display = 'block';
  } else {
    document.getElementById('admin-setup-form').style.display = 'none';
    lockScreen.style.display = '';
  }

  document.getElementById('admin-setup-form')?.addEventListener('submit', (e) => {
    e.preventDefault();
    const pw = document.getElementById('admin-setup-password').value;
    if (pw.length < 4) { alert(t('admin.passwordMinChars')); return; }
    localStorage.setItem(ADMIN_PW_KEY, pw);
    lockScreen.style.display = 'none';
    content.classList.remove('hidden');
    showToast(t('admin.passwordUpdated'));
    initAdminContent();
  });

  document.getElementById('admin-login-form')?.addEventListener('submit', (e) => {
    e.preventDefault();
    const input = document.getElementById('admin-password-input');
    if (input.value === localStorage.getItem(ADMIN_PW_KEY)) {
      input.value = '';
      lockScreen.style.display = 'none';
      content.classList.remove('hidden');
      initAdminContent();
    } else {
      document.getElementById('admin-error').textContent = t('admin.wrongPassword');
    }
  });

  document.getElementById('admin-logout-btn')?.addEventListener('click', () => {
    document.getElementById('admin-content').classList.add('hidden');
    document.getElementById('admin-lock-screen').style.display = '';
    var pwInput = document.getElementById('admin-password-input');
    if (pwInput) pwInput.value = '';
  });

  // Clear password on navigation back/forward (bfcache)
  window.addEventListener('pageshow', function() {
    var pwInput = document.getElementById('admin-password-input');
    if (pwInput) pwInput.value = '';
  });
  document.addEventListener('visibilitychange', function() {
    if (document.visibilityState === 'hidden') {
      var pwInput = document.getElementById('admin-password-input');
      if (pwInput) pwInput.value = '';
    }
  });
}

function initAdminContent() {
  if (_adminContentWired) {
    renderKeys();
    initDocManager();
    renderDiplomasTable();
    renderSpecialtiesTable();
    return;
  }
  _adminContentWired = true;

  // Tabs
  document.querySelectorAll('.admin-tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.admin-tab-btn').forEach(b => b.classList.remove('active'));
      document.querySelectorAll('.admin-tab-panel').forEach(p => p.classList.add('hidden'));
      btn.classList.add('active');
      document.getElementById('tab-panel-' + btn.dataset.tab).classList.remove('hidden');
    });
  });

  // Docs sub-tab switching
  var docsSubTabs = document.querySelectorAll('#tab-panel-docs .admin-sub-tab');
  docsSubTabs.forEach(function(btn) {
    btn.addEventListener('click', function() {
      docsSubTabs.forEach(function(b) { b.classList.remove('active'); });
      document.querySelectorAll('#tab-panel-docs .admin-sub-panel').forEach(function(p) { p.classList.add('hidden'); });
      btn.classList.add('active');
      var panel = document.getElementById('sub-panel-' + btn.dataset.subtab);
      if (panel) panel.classList.remove('hidden');
    });
  });

  // Init documents
  initDocManager();
  initImportTab();

  // Init structure (diplomas, semesters, modules, specialties)
  initStructureTab();

  // Init keys
  renderKeys();

  document.getElementById('add-key-form')?.addEventListener('submit', function(e) {
    e.preventDefault();
    var provider = document.getElementById('key-provider').value;
    var apiKey = sanitizeApiKey(document.getElementById('key-api-key').value);
    var model = document.getElementById('key-model').value.trim() || (PROVIDERS[provider] ? PROVIDERS[provider].defaultModel : '');
    if (!apiKey) { showToast('Cl\u00e9 API requise'); return; }
    var keys = getStoredKeys();
    if (editingKeyIdx !== null && keys[editingKeyIdx]) {
      keys[editingKeyIdx].provider = provider;
      keys[editingKeyIdx].apiKey = apiKey;
      keys[editingKeyIdx].model = model;
      showToast(t('admin.keyUpdated') || 'Cl\u00e9 modifi\u00e9e');
    } else {
      var newKey = { id: 'key-' + Date.now(), provider: provider, apiKey: apiKey, model: model, active: keys.length === 0 };
      keys.push(newKey);
      showToast(t('admin.keyAdded') || 'Cl\u00e9 ajout\u00e9e');
    }
    saveStoredKeys(keys);
    editingKeyIdx = null;
    renderKeys();
    document.getElementById('add-key-form').reset();
    document.getElementById('add-key-form').querySelector('[type="submit"]').textContent = t('admin.addProvider') || 'Ajouter';
  });

  // Auto-detect provider when pasting API key
  document.getElementById('key-api-key')?.addEventListener('input', function() {
    var val = this.value.trim();
    if (typeof detectProvider === 'function') {
      var detected = detectProvider(val);
      if (detected) {
        document.getElementById('key-provider').value = detected;
        var modelInput = document.getElementById('key-model');
        if (modelInput && !modelInput.value) modelInput.placeholder = 'Mod\u00e8le: ' + (PROVIDERS[detected] ? PROVIDERS[detected].defaultModel : '');
      }
    }
  });

  // Reset edit mode on cancel
  document.getElementById('key-api-key')?.addEventListener('focus', function() {
    if (editingKeyIdx !== null) {
      editingKeyIdx = null;
      document.getElementById('add-key-form').reset();
      document.getElementById('add-key-form').querySelector('[type="submit"]').textContent = t('admin.addProvider') || 'Ajouter';
    }
  });

  // Tab-to-fill: pressing Tab on an empty field with placeholder fills it
  document.addEventListener('keydown', function(e) {
    if (e.key !== 'Tab') return;
    var el = document.activeElement;
    if (!el || el.tagName === 'SELECT' || el.tagName === 'BUTTON') return;
    if (!el.closest('#doc-form')) return;
    if (el.value || !el.placeholder) return;
    e.preventDefault();
    el.value = el.placeholder;
    var form = el.closest('form');
    if (!form) return;
    var inputs = Array.from(form.querySelectorAll('input, textarea, select'));
    var idx = inputs.indexOf(el);
    if (idx >= 0 && idx < inputs.length - 1) {
      inputs[idx + 1].focus();
    }
  });

  // Change password
  document.getElementById('change-password-form')?.addEventListener('submit', (e) => {
    e.preventDefault();
    const old = document.getElementById('change-password-old').value;
    const newPw = document.getElementById('change-password-new').value;
    if (old !== localStorage.getItem(ADMIN_PW_KEY)) { showToast(t('admin.wrongPassword')); return; }
    if (newPw.length < 4) { alert(t('admin.passwordMinChars')); return; }
    localStorage.setItem(ADMIN_PW_KEY, newPw);
    showToast(t('admin.passwordUpdated'));
    document.getElementById('change-password-form').reset();
  });
}

